if (polygon.size() < 3) {
    return ON_UNBOUNDED_SIDE;
}

bool inside = false;
int n = polygon.size();

for (int i = 0, j = n - 1; i < n; j = i++) {
    const Point_2& pi = polygon[i];
    const Point_2& pj = polygon[j];

    // Check if point is on the edge pj-pi
    // Using orientation test
    auto orient = CGAL::orientation(pj, pi, point);
    if (orient == COLLINEAR) {
        // Check if point is between pj and pi
        if ((std::min(pi.x(), pj.x()) <= point.x() && point.x() <= std::max(pi.x(), pj.x())) &&
            (std::min(pi.y(), pj.y()) <= point.y() && point.y() <= std::max(pi.y(), pj.y()))) {
            return ON_BOUNDARY;
        }
    }

    // Ray casting algorithm
    // Check if the edge crosses the horizontal ray from the point going right
    bool intersect = false;

    // Check if the edge crosses the ray
    if (((pi.y() > point.y()) != (pj.y() > point.y())) &&
        (point.x() < (pj.x() - pi.x()) * (point.y() - pi.y()) / (pj.y() - pi.y()) + pi.x())) {
        inside = !inside;
    }
}

return inside ? ON_BOUNDED_SIDE : ON_UNBOUNDED_SIDE;

